-- Source: HS.json, UN Comtrade reference list for classification HS (Combined HS).
-- Names are the file's text after the '<code> - ' prefix, otherwise unchanged.
-- Encoding: UTF-8. Portable SQL (SQLite and PostgreSQL).

DROP TABLE IF EXISTS hs6;
DROP TABLE IF EXISTS hs4;
DROP TABLE IF EXISTS hs2;

-- Chapters: digits 1-2, e.g. 01 "Animals; live".
CREATE TABLE hs2 (
    hs2_code CHAR(2) NOT NULL PRIMARY KEY,
    name     TEXT    NOT NULL,
    CHECK (length(hs2_code) = 2)
);

-- Headings: digits 3-4 within a chapter, e.g. 0105 "Poultry; live, fowls of the species ...".
CREATE TABLE hs4 (
    hs4_code CHAR(4) NOT NULL PRIMARY KEY,
    hs2_code CHAR(2) NOT NULL REFERENCES hs2 (hs2_code),
    name     TEXT    NOT NULL,
    CHECK (length(hs4_code) = 4),
    CHECK (hs2_code = substr(hs4_code, 1, 2))
);
CREATE INDEX ix_hs4_hs2_code ON hs4 (hs2_code);

-- Subheadings: digits 5-6 within a heading, e.g. 010511 "Poultry; live, fowls of the species
-- gallus domesticus, weighing not more than 185g".
CREATE TABLE hs6 (
    hs6_code CHAR(6) NOT NULL PRIMARY KEY,
    hs4_code CHAR(4) NOT NULL REFERENCES hs4 (hs4_code),
    name     TEXT    NOT NULL,
    CHECK (length(hs6_code) = 6),
    CHECK (hs4_code = substr(hs6_code, 1, 4))
);
CREATE INDEX ix_hs6_hs4_code ON hs6 (hs4_code);
